export function StickyHeader({
  title = "{{title}}",
  bg = "{{bg}}",
  align = "{{align}}",
  shadow = {{shadow}},
}) {
  const paragraphs = [
    "Scroll down inside this box. The header above uses position: sticky with top: 0, so it stays pinned to the top of this scroll container instead of scrolling away with the text.",
    "It only sticks within its own scrolling ancestor — once that ancestor ends, the header scrolls away too.",
    "A third paragraph adds enough height to make scrolling necessary.",
    "A fourth paragraph, for good measure.",
    "And a fifth, so the sticky behaviour is unmistakable.",
  ];
  return (
    <div style={{ height: 160, overflowY: "auto", border: "1px solid #24143022", fontFamily: "system-ui, sans-serif", fontSize: 13, lineHeight: 1.6, color: "#241430" }}>
      <div style={{ position: "sticky", top: 0, zIndex: 2, background: bg, padding: "10px 14px", fontWeight: 700, textAlign: align === "center" ? "center" : "left", boxShadow: shadow ? "0 4px 10px rgba(36,20,48,.2)" : "none" }}>{title}</div>
      {paragraphs.map((p, i) => <p key={i} style={{ margin: 0, padding: "10px 14px 0", color: "#241430cc" }}>{p}</p>)}
    </div>
  );
}
